import sys, html.parser
class P(html.parser.HTMLParser):
    def __init__(s): super().__init__(); s.out=[]; s.skip=0
    def handle_starttag(s,t,a):
        if t in('script','style','svg'): s.skip+=1
        if t in('p','div','li','h1','h2','h3','h4','pre','tr','br','section'): s.out.append('\n')
        if t in('h1','h2','h3','h4'): s.out.append('#'*int(t[1])+' ')
        if t=='li': s.out.append('- ')
        if t=='code' : s.out.append('`')
    def handle_endtag(s,t):
        if t in('script','style','svg'): s.skip-=1
        if t=='code': s.out.append('`')
    def handle_data(s,d):
        if not s.skip: s.out.append(d)
p=P(); p.feed(open(sys.argv[1]).read())
import re
t=''.join(p.out); t=re.sub(r'\n\s*\n+','\n\n',t); print(t)
EOF
